const email = $json.body?.email;
if (!email) {
  throw new Error('O webhook precisa enviar body.email (ex: {"email":"usuario@dominio.com"}).');
}
return [{ json: { email } }];

const email = $json.email;

const locatorPy = `import os

def try_exec(path: str):
    if os.path.isfile(path):
        g = {"__name__": "__main__"}
        with open(path, "r", encoding="utf-8") as f:
            code = f.read()
        exec(compile(code, path, 'exec'), g)
        return True
    return False

cands = []
for base in ['.', '/app', '/workspace', '/home/node', '/opt']:
    for rel in [
        'n8n/otto_admin_selenium_reset_password_n8n_env.py',
        './n8n/otto_admin_selenium_reset_password_n8n_env.py',
        'otto_admin_selenium_reset_password_n8n_env.py'
    ]:
        if base == '.' and rel.startswith('./'):
            cands.append(rel[2:])
        elif base == '.':
            cands.append(rel)
        else:
            cands.append(os.path.join(base, rel))

for p in cands:
    if try_exec(p):
        break
else:
    raise FileNotFoundError('Nao encontrei otto_admin_selenium_reset_password_n8n_env.py em: ' + ', '.join(cands))
`;

const cmd = [
  'python3 -c "import selenium" >/dev/null 2>&1 || python3 -m pip install --user -q selenium webdriver-manager >/dev/null 2>&1',
  `PYTHONUNBUFFERED=1 OTTO_TARGET_EMAIL=${JSON.stringify(email)} python3 -c ${JSON.stringify(locatorPy)}`
].join('; ');

return [{ json: { command: cmd } }];

const raw = items?.[0]?.json ?? {};
const stdout = String(raw.stdout ?? '').trim();
const stderr = String(raw.stderr ?? '').trim();

let payload = null;
try {
  payload = JSON.parse(stdout);
} catch (e) {
  // stdout pode vir com logs extra; tenta a ultima linha parseável
  const lines = stdout.split(/\r?\n/).map((x) => x.trim()).filter(Boolean);
  for (let i = lines.length - 1; i >= 0; i--) {
    try {
      payload = JSON.parse(lines[i]);
      break;
    } catch (e2) {
      // continua tentando
    }
  }
}

if (!payload || typeof payload !== 'object') {
  return [{
    json: {
      ok: false,
      status: 'erro_parse_stdout',
      stdout,
      stderr,
      hint: 'Nao foi possivel interpretar JSON do Execute Command.'
    }
  }];
}

return [{
  json: {
    ...payload,
    _meta: {
      stderr
    }
  }
}];
